from itertools import chain


def prepend_value(value: str, iterable: list[str]) -> list[str]:
    """Add a value to the beginning of an iterable. value: The value to prepend to the iterable, iterable: The iterable to prepend the value to. >>> prepend_value('0', ['1', '2', '3']) ['0', '1', '2', '3']"""
    try:
        result = list(chain([value], iterable))
        return result
    except Exception as e:
        raise ValueError(f"Failed to prepend value: {e}") from e
```

